mapper.update:
merge into t_gdyy_loss_setting a USING (
select #{QuotaSetting.bigRollCode,jdbcType=VARCHAR} big_roll_code, #{QuotaSetting.lossRate,jdbcType=DOUBLE} loss_rate, #{QuotaSetting.createBy,jdbcType=VARCHAR} create_by, #{QuotaSetting.createTime,jdbcType=DATE} create_time, #{QuotaSetting.updateBy,jdbcType=VARCHAR} update_by, #{QuotaSetting.updateTime,jdbcType=DATE} update_time, #{QuotaSetting.remark,jdbcType=VARCHAR} remark from dual
) b ON ( ((b.big_roll_code is null and a.big_roll_code is null) or (a.big_roll_code = b.big_roll_code)) AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.loss_rate = b.loss_rate, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT (a.id, a.big_roll_code, a.loss_rate, a.create_by, a.create_time, a.remark, a.del_flag) values (SEQ_QUOTA_SETTING.NEXTVAL, b.big_roll_code, b.loss_rate, b.create_by, sysdate, b.remark, '0')
